internal fun NativeArena.putRenderedFeatureQueryOptions(
  target: Long,
  value: RenderedFeatureQueryOptions,
) {
  C.mln_rendered_feature_query_options_default(target)
  writeU32(target + 4, 0u)
  value.layerIds?.let {
    writeU32(target + 4, readU32(target + 4) or 1u)
    writeAddress(
      target + 8,
      array(it, 2 * NativeMemory.addressSize, NativeMemory.addressSize) { at, item ->
        putView(at, item)
      },
    )
    writeSize(target + w(12, 16), it.size.toULong())
  }
  writeAddress(target + w(16, 24), value.filter?.let { view(it) } ?: 0L)
}

internal fun NativeArena.writeRenderedFeatureQueryOptions(
  value: RenderedFeatureQueryOptions
): Long = allocate(w(20, 32), w(4, 8)).also { putRenderedFeatureQueryOptions(it, value) }

