    bounds = if ((readU32(source + 4) and 1u) != 0u) readLatLngBounds(source + 8) else null,
    minZoom = if ((readU32(source + 4) and 2u) != 0u) readF64(source + 40) else null,
    maxZoom = if ((readU32(source + 4) and 4u) != 0u) readF64(source + 48) else null,
    minPitch = if ((readU32(source + 4) and 8u) != 0u) readF64(source + 56) else null,
    maxPitch = if ((readU32(source + 4) and 16u) != 0u) readF64(source + 64) else null,
  )

